        wait::poll(timeout, || {
            let fut = self.get(GetOnlineTableRequest::default().with_name(param.clone()));
            async move {
                let value = fut.await?;
                if let Some(cb) = callback
                    .lock()
                    .unwrap_or_else(::std::sync::PoisonError::into_inner)
                    .as_mut()
                {
                    cb(&value);
                }
                wait::check_state(
                    value,
                    wait::States {
                        status_path: &["unity_catalog_provisioning_state"],
                        message_path: &[],
                        targets: &["ACTIVE"],
                        failures: &["FAILED"],
                    },
                )
            }
        })
