/// Returned by operations that start a long-running change; waits until
/// the result reaches ACTIVE.
pub struct WaitGetOnlineTableActive<R> {
    api: OnlineTablesApi,
    /// The ID being waited on.
    pub name: String,
    /// The operation's immediate response.
    pub response: R,
    timeout: ::std::time::Duration,
    on_progress: Option<wait::Progress<OnlineTable>>,
}

impl<R: ::std::fmt::Debug> ::std::fmt::Debug for WaitGetOnlineTableActive<R> {
    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        f.debug_struct("WaitGetOnlineTableActive")
            .field("name", &self.name)
            .field("response", &self.response)
            .field("timeout", &self.timeout)
            .finish_non_exhaustive()
    }
}

impl<R> WaitGetOnlineTableActive<R> {
    /// Override the default timeout.
    #[must_use]
    pub fn timeout(mut self, timeout: ::std::time::Duration) -> Self {
        self.timeout = timeout;
        self
    }

    /// Called with the polled value on every poll.
    #[must_use]
    pub fn on_progress(mut self, f: impl FnMut(&OnlineTable) + Send + 'static) -> Self {
        self.on_progress = Some(Box::new(f));
        self
    }

    /// Wait until the result reaches ACTIVE.
    pub async fn wait(self) -> ::community_databricks_core::Result<OnlineTable> {
        self.api
            .wait_get_online_table_active(self.name, self.timeout, self.on_progress)
            .await
    }
}

